preConditionHook:
// UNDERCUT OF THE LOWER SWING BELOW A LEVEL PAIR (Brian's notes ON-11, #11,
// p.11). The two most recent swing lows sit at about the same level (within
// pairTolAtr ATRs of each other); the swing low before them (occurrence 3) is
// between minBelowAtr and maxBelowAtr ATRs below the lower of the pair and has
// not been traded below since it formed. This bar's low goes below that
// earlier swing low and the bar closes back above it: long. Short mirrors at
// swing highs. Swing strength is not stated in the note ("identify ATR
// threshold by eye"); 2 is the default.
//
//
// Pivot scan hand-rolled as in SwingPivotTarget (the register lists SwingHigh's
// Occurrence 3+ as unmeasured, and a lagged SwingHigh read is unregistered).
// MEASURED (EL_Swing_Probe.txt): the pivot bar is AT OR ABOVE the swingStrength
// OLDER bars and STRICTLY ABOVE the swingStrength NEWER bars -- bars-ago
// indexing, so the newer bars are the smaller kk; lag exactly swingStrength;
// the low side's tie sense mirrors the measured high side. No Break -- not a
// registered word.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right,
// and folding it to S += in - out rounds differently. The local counter is
// atrLen, not the input.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
nHi = 0;
nLo = 0;
hiPx1 = 0.0;
hiPx2 = 0.0;
hiPx3 = 0.0;
hiBar3 = 0;
loPx1 = 0.0;
loPx2 = 0.0;
loPx3 = 0.0;
loBar3 = 0;
for (int jj = (int)swingStrength; jj <= (int)pivotLookback - 1; ++jj) {
    okHi = true;
    okLo = true;
    for (int kk = jj - (int)swingStrength; kk <= jj - 1; ++kk) {
        if (el_le(high[jj], high[kk])) okHi = false;
        if (el_ge(low[jj], low[kk])) okLo = false;
    }
    for (int kk = jj + 1; kk <= jj + (int)swingStrength; ++kk) {
        if (el_lt(high[jj], high[kk])) okHi = false;
        if (el_gt(low[jj], low[kk])) okLo = false;
    }
    if (okHi && nHi < 3) {
        nHi = nHi + 1;
        if (nHi == 1) hiPx1 = high[jj];
        if (nHi == 2) hiPx2 = high[jj];
        if (nHi == 3) {
            hiPx3 = high[jj];
            hiBar3 = jj;
        }
    }
    if (okLo && nLo < 3) {
        nLo = nLo + 1;
        if (nLo == 1) loPx1 = low[jj];
        if (nLo == 2) loPx2 = low[jj];
        if (nLo == 3) {
            loPx3 = low[jj];
            loBar3 = jj;
        }
    }
}
fireL = false;
fireS = false;
if (nLo == 3) {
    if (el_le(std::fabs(loPx1 - loPx2), pairTolAtr * atrVal)) {
        gap = loPx1 - loPx3;
        if (el_lt(loPx2, loPx1)) gap = loPx2 - loPx3;
        if (el_ge(gap, minBelowAtr * atrVal) && el_le(gap, maxBelowAtr * atrVal)) {
            okU = true;
            for (int kk = 1; kk <= loBar3 - 1; ++kk) {
                if (el_lt(low[kk], loPx3)) okU = false;
            }
            if (okU && el_lt(low[0], loPx3) && el_gt(close[0], loPx3)) fireL = true;
        }
    }
}
if (nHi == 3) {
    if (el_le(std::fabs(hiPx1 - hiPx2), pairTolAtr * atrVal)) {
        gap = hiPx3 - hiPx1;
        if (el_gt(hiPx2, hiPx1)) gap = hiPx3 - hiPx2;
        if (el_ge(gap, minBelowAtr * atrVal) && el_le(gap, maxBelowAtr * atrVal)) {
            okU = true;
            for (int kk = 1; kk <= hiBar3 - 1; ++kk) {
                if (el_gt(high[kk], hiPx3)) okU = false;
            }
            if (okU && el_gt(high[0], hiPx3) && el_lt(close[0], hiPx3)) fireS = true;
        }
    }
}
